python3 -c "
import os
import json

# Check OpenRouter config
config_path = os.path.expanduser('~/.openclaw/config/providers.json')
if os.path.exists(config_path):
    config = json.load(open(config_path))
    print('Providers config exists')
    if 'openrouter' in config:
        or_cfg = config['openrouter']
        if 'apiKey' in or_cfg:
            key_preview = or_cfg['apiKey'][:8] + '...' if or_cfg['apiKey'] else 'NOT SET'
            print(f'OpenRouter apiKey: {key_preview}')
        else:
            print('OpenRouter apiKey: NOT FOUND')
    else:
        print('OpenRouter section: NOT FOUND')
else:
    print('Providers config: NOT FOUND')

# Check environment
env_key = os.environ.get('OPENROUTER_API_KEY', '')
if env_key:
    print(f'ENV OPENROUTER_API_KEY: {env_key[:8]}...')
else:
    print('ENV OPENROUTER_API_KEY: NOT SET')
"

