    print(f'  {k}')

# Check for any image-related config
print()
print('=== Searching for image generation config ===')
def find_image_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'image' in k.lower() or 'generation' in k.lower():
                print(f'{new_path}: {v}')
            find_image_keys(v, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_image_keys(item, f'{path}[{i}]')

find_image_keys(cfg)
